#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    const char *input = "";
    if (argc > 1) {
        input = argv[1];
    }
    size_t len = strlen(input);
    if (len > 0x400) { // 1024 characters
        puts("TOO_LONG");
        return 0;
    }
    char norm[0x401]; // enough for normalized string (max 1024 chars)
    size_t n = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char ch = (unsigned char)input[i];
        if (isalnum(ch)) {
            norm[n++] = (char)toupper(ch);
        }
    }
    norm[n] = '\0';
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }
    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
